/*
 * A075836  Numbers k such that 10*k^2 + 9 is a square.
 * https://oeis.org/A075836
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   * a(3*m+1) = k from the sequence generated by (k,m)=(0,3) *
 *            a(3*m+2) = k from the sequence generated by (k,m)=(2,7) *
 *            a(3*m+3) = k from the sequence generated by (k,m)=(4,13) * *
 *            Recurrence for each family: * m_next = 19*m + 60*k * k_next =
 *            6*m + 19*k * * These three interleaved sequences produce...
 * Range:     u8 n <= 6, u16 n <= 10, u32 n <= 19, u64 n <= 37, u128 n <= 75,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* maximum number of terms per family that we need to store.
   For n <= 10000 the required index per family is at most 3333,
   so 5000 is more than enough.                     */
#define FAMILY_CAP 5000

/* state for each of the three families */
static seq_t family_k[3][FAMILY_CAP];
static seq_t family_last_k[3];
static seq_t family_last_m[3];
static size_t family_len[3] = {0, 0, 0};
static int families_initialized = 0;

/* helper to initialise the three families the first time a() is called */
static void init_families(void)
{
    if (families_initialized)
        return;

    /* family 0 : (k,m) = (0,3) */
    family_k[0][0] = (seq_t)0;
    family_last_k[0] = (seq_t)0;
    family_last_m[0] = (seq_t)3;
    family_len[0] = 1;

    /* family 1 : (k,m) = (2,7) */
    family_k[1][0] = (seq_t)2;
    family_last_k[1] = (seq_t)2;
    family_last_m[1] = (seq_t)7;
    family_len[1] = 1;

    /* family 2 : (k,m) = (4,13) */
    family_k[2][0] = (seq_t)4;
    family_last_k[2] = (seq_t)4;
    family_last_m[2] = (seq_t)13;
    family_len[2] = 1;

    families_initialized = 1;
}

/* ensure that family 'fam' has at least target_index+1 elements stored.
 * target_index is 0‑based. */
static void ensure_family_len(int fam, size_t target_index)
{
    while (family_len[fam] <= target_index) {
        /* compute next (m,k) */
        seq_t new_m = (seq_t)19 * family_last_m[fam] +
                      (seq_t)60 * family_last_k[fam];
        seq_t new_k = (seq_t)6  * family_last_m[fam] +
                      (seq_t)19 * family_last_k[fam];

        family_last_m[fam] = new_m;
        family_last_k[fam] = new_k;
        family_k[fam][family_len[fam]++] = new_k;
    }
}

/*-------------------------------------------------------------*/
seq_t a(idx_t n)
{
    /* a(1) corresponds to n=1 in the OEIS convention */
    if (n < 1)
        return (seq_t)0;  /* undefined region; return 0 */

    init_families();

    idx_t overall_index = n - 1;          /* 0‑based */
    int family = overall_index % 3;       /* which family contributes */
    size_t fam_index = overall_index / 3; /* 0‑based index within the family */

    ensure_family_len(family, fam_index);

    return family_k[family][fam_index];
}
